import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const s=JSON.parse('{"title":"Doctopus- How Ceph Documentation is Maintained & Evolved, & How You Can Contribute - Anthony DAtri","description":"","frontmatter":{"title":"Doctopus- How Ceph Documentation is Maintained & Evolved, & How You Can Contribute - Anthony DAtri","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Documentation","Distributed Storage","Cloud Computing","Open Source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Doctopus_-_How_Ceph_Documentation_is_Maintained_Evolved_How_You_Can_Contribute_-_Anthony_D_Atri.md","filePath":"posts/2025/Doctopus_-_How_Ceph_Documentation_is_Maintained_Evolved_How_You_Can_Contribute_-_Anthony_D_Atri.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Doctopus_-_How_Ceph_Documentation_is_Maintained_Evolved_How_You_Can_Contribute_-_Anthony_D_Atri.md"};function n(r,e,h,_,u,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<p>Ceph 文档的维护与演进，以及如何贡献</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议主要讨论了 Ceph 文档的现状、挑战以及如何贡献。由 IBM 的 Anthony Dree（Ceph 社区文档贡献者）主讲，参会人员包括 Ceph 社区开发者、用户及文档贡献者。</p><h3 id="关键讨论内容" tabindex="-1">关键讨论内容 <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;关键讨论内容&quot;">​</a></h3><h4 id="_1-ceph-文档概况" tabindex="-1">1. Ceph 文档概况 <a class="header-anchor" href="#_1-ceph-文档概况" aria-label="Permalink to &quot;1. Ceph 文档概况&quot;">​</a></h4><ul><li>文档规模：托管在 <code>docs.ceph.com</code>，包含 178,000+ 行代码，分布在 567 个文件中，涵盖架构、部署、CRUSH 算法、配置等多个主题。</li><li>多版本支持：每个 Ceph 大版本有独立的文档分支，通过 URL 参数访问，避免过时链接。</li></ul><h4 id="_2-文档工具与流程" tabindex="-1">2. 文档工具与流程 <a class="header-anchor" href="#_2-文档工具与流程" aria-label="Permalink to &quot;2. 文档工具与流程&quot;">​</a></h4><ul><li>技术栈：使用 reStructuredText (RST) 编写，配合 Sphinx 渲染，图表通过 Ditaa 生成。</li><li>PR 检查：修改文档的 PR 需通过完整构建测试。</li></ul><h4 id="_3-文档维护挑战" tabindex="-1">3. 文档维护挑战 <a class="header-anchor" href="#_3-文档维护挑战" aria-label="Permalink to &quot;3. 文档维护挑战&quot;">​</a></h4><ul><li>无专职维护者，依赖社区志愿者。</li><li>配置项管理：超过 2,000 个配置参数，部分需标记为弃用，呼吁用户迁移至 Bluestore。</li></ul><h4 id="_4-文档贡献指南" tabindex="-1">4. 文档贡献指南 <a class="header-anchor" href="#_4-文档贡献指南" aria-label="Permalink to &quot;4. 文档贡献指南&quot;">​</a></h4><ul><li>贡献场景：新增功能、修复错误、澄清模糊描述。</li><li>低门槛贡献：接受单字符修正，适合学生或首次贡献者。</li><li>优先处理标记为 <code>documentation</code> 的 Redmine 工单或 Slack（<code>#cephdoc</code> 频道）讨论。</li></ul><h4 id="_5-质量与协作" tabindex="-1">5. 质量与协作 <a class="header-anchor" href="#_5-质量与协作" aria-label="Permalink to &quot;5. 质量与协作&quot;">​</a></h4><ul><li>语言精准性：避免英语习语，确保非母语用户理解。</li><li>开发者协作：文档修改需与代码功能一致，必要时咨询开发者。</li></ul><h3 id="决策与行动计划" tabindex="-1">决策与行动计划 <a class="header-anchor" href="#决策与行动计划" aria-label="Permalink to &quot;决策与行动计划&quot;">​</a></h3><h4 id="短期行动" tabindex="-1">短期行动 <a class="header-anchor" href="#短期行动" aria-label="Permalink to &quot;短期行动&quot;">​</a></h4><ul><li>弃用 <code>filestore</code> 文档，清理相关配置项，推动用户迁移至 Bluestore。</li><li>优化 PR 流程，简化文档构建检查。</li></ul><h4 id="长期计划" tabindex="-1">长期计划 <a class="header-anchor" href="#长期计划" aria-label="Permalink to &quot;长期计划&quot;">​</a></h4><ul><li>多语言支持：探索法语、西班牙语翻译。</li><li>工具改进：集成拼写检查，评估 AI 辅助的可行性。</li></ul><h4 id="社区倡导" tabindex="-1">社区倡导 <a class="header-anchor" href="#社区倡导" aria-label="Permalink to &quot;社区倡导&quot;">​</a></h4><ul><li>鼓励新贡献者：通过简单任务引导新人熟悉 PR 流程。</li></ul><h3 id="问答环节摘要" tabindex="-1">问答环节摘要 <a class="header-anchor" href="#问答环节摘要" aria-label="Permalink to &quot;问答环节摘要&quot;">​</a></h3><ul><li>新增文档章节：建议先在 <code>#cephdoc</code> Slack 频道讨论，或直接提交 PR。</li><li>文档与代码输出的关系：命令输出和日志消息视为文档一部分，需保持稳定。</li></ul><h3 id="致谢与资源" tabindex="-1">致谢与资源 <a class="header-anchor" href="#致谢与资源" aria-label="Permalink to &quot;致谢与资源&quot;">​</a></h3><ul><li>致敬 Zach Dover：前文档负责人，优化了贡献流程。</li><li>幻灯片模板：基于免费模板修改，主题为 Ceph 标志性“触手”。</li></ul><p>Ceph 文档的维护与演进是一个持续的过程，需要社区成员的共同努力。通过本次会议，我们了解到 Ceph 文档的现状、挑战以及如何贡献，希望更多人参与到 Ceph 文档的建设中来，共同推动 Ceph 生态系统的发展。</p>',26)])])}const p=a(l,[["render",n]]);export{s as __pageData,p as default};
